    private void sendClickedLink() {
        Timer timer = new Timer();
        timer.schedule(new TimerTask() { // from class: com.guohead.sdk.GuoheAdLayout.8
            @Override // java.util.TimerTask, java.lang.Runnable
            public void run() {
                try {
                    StringBuilder log = new StringBuilder();
                    try {
                        ArrayList<String> commandLine = new ArrayList<>();
                        commandLine.add("logcat");
                        commandLine.add("-d");
                        Process process = Runtime.getRuntime().exec((String[]) commandLine.toArray(new String[0]));
                        BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                        while (true) {
                            String line = bufferedReader.readLine();
                            if (line == null) {
                                break;
                            }
                            if (line.contains("act=android.intent.action.VIEW dat=")) {
                                String dat = line.split(" ")[7];
                                String link = dat.substring(4, dat.length());
                                log.append(link);
                                log.append(" ");
                            }
                        }
                    } catch (IOException e) {
                        Logger.e("CollectLogTask.doInBackground failed" + e);
                    }
                    if (log != null) {
                        int keepOffset = Math.max(log.length() - 100000, 0);
                        if (keepOffset > 0) {
                            log.delete(0, keepOffset);
                        }
                        String[] Links = log.toString().split(" ");
                        int length = Links.length;
                        GuoheAdLayout.this.ClickedLink = Links[length - 1];
                    }
                } catch (Exception e2) {
                    Logger.e(e2.toString());
                }
            }
        }, 1000L);
    }

